            C++

    #include <iostream>
using namespace std;

int numberOfPaths(int m, int n) {

    // dp[j] stores paths to current cell in the row
    int dp[n] = {1};

    // Only one way to reach first column
    dp[0] = 1; 

    for (int i = 0; i < m; i++) {
        for (int j = 1; j < n; j++) {

            // Paths from top (dp[j]) + left (dp[j-1])
            dp[j] += dp[j - 1];
        }
    }

    // Paths to bottom-right cell
    return dp[n - 1];
}

int main() {
    int res = numberOfPaths(2, 3);
    cout << res << endl;
}


